/* Start [ MGCMTBLDAT Table(TABLE_NAME) : ID_GEN_TRAN_CODE] */
BEGIN
   FOR REC IN (
       SELECT DISTINCT FACTORY FROM MWIPFACDEF
       MINUS
       SELECT DISTINCT FACTORY FROM MGCMTBLDAT
       WHERE TABLE_NAME = 'ID_GEN_TRAN_CODE'
        AND KEY_1 = 'CREATE_BIN'
       )
   LOOP
   VALUES(REC.FACTORY,'ID_GEN_TRAN_CODE', 'CREATE_BIN', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', 'Create BIN ID', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', ' ', 'ADMIN', '20130220115837', ' ', ' ');
   END LOOP;
END;
/
/* End [ MGCMTBLDAT Table(TABLE_NAME) : ID_GEN_TRAN_CODE] */

